function daoaiHeaderInit() {

    // ── Mobile drawer scroll-lock (CSS handles the show/hide via checkbox) ──
    var menuCheckbox = document.getElementById('daoai-mobile-menu-toggle');

    if (menuCheckbox) {
        menuCheckbox.addEventListener('change', function () {
            document.body.style.overflow = menuCheckbox.checked ? 'hidden' : '';
        });
    }

    // Close drawer when a nav link inside it is clicked
    document.addEventListener('click', function (e) {
        if (e.target.closest('.header-mobile-drawer a')) {
            if (menuCheckbox) {
                menuCheckbox.checked = false;
                document.body.style.overflow = '';
            }
            var drawer = document.querySelector('.header-mobile-drawer');
            if (drawer) drawer.classList.remove('active');
        }
    });

    // ── Contact modal ──
    var contactModal = document.getElementById('daoai-contact-modal');
    if (!contactModal) return;

    function openContactModal() {
        contactModal.classList.add('is-open');
        document.body.style.overflow = 'hidden';

        // Close mobile drawer
        if (menuCheckbox) {
            menuCheckbox.checked = false;
        }
        var drawer = document.querySelector('.header-mobile-drawer');
        if (drawer) {
            drawer.classList.remove('active');
            drawer.style.setProperty('display', 'none', 'important');
        }
    }

    function closeContactModal() {
        contactModal.classList.remove('is-open');
        document.body.style.overflow = '';
    }

    // Open triggers — event delegation catches ALL clicks (including dynamically added elements)
    document.addEventListener('click', function (e) {
        // [data-contact-modal-trigger] on any element
        if (e.target.closest('[data-contact-modal-trigger]')) {
            e.preventDefault();
            openContactModal();
            return;
        }
        // Any link whose href contains "/contact-us" (catches www, full URL, relative, etc.)
        var link = e.target.closest('a[href*="/contact-us"]');
        if (link) {
            e.preventDefault();
            openContactModal();
        }
    });

    // Form submission via AJAX
    var form = contactModal.querySelector('.hs-form');
    var _formLoadTime = Date.now();
    if (form) {
        form.addEventListener("submit", function (e) {
            e.preventDefault();
            var submitBtn = form.querySelector('button[type="submit"]');
            var originalBtnText = submitBtn.innerText;
            submitBtn.innerText = 'Sending...';
            submitBtn.disabled = true;

            var data = new FormData(form);
            data.append('_fill_time', ((Date.now() - _formLoadTime) / 1000).toFixed(1));
            fetch(form.action, {
                method: form.method,
                body: data,
                headers: {
                    'Accept': 'application/json'
                }
            }).then(function (response) {
                return response.json().then(function (data) {
                    if (response.ok && data.ok !== false) {
                        form.reset();
                        var wrap = document.querySelector('.contact-modal-form-wrap');
                        if (wrap) {
                            wrap.innerHTML = `
                            <div style="text-align: center; padding: 3rem 1rem;">
                                <div style="width: 72px; height: 72px; background: #203f56; border-radius: 50%; display: flex; align-items: center; justify-content: center; margin: 0 auto 1.5rem auto;">
                                    <svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="#38bdf8" stroke-width="3" stroke-linecap="round" stroke-linejoin="round">
                                        <polyline points="20 6 9 17 4 12"></polyline>
                                    </svg>
                                </div>
                                <h3 style="color: #38bdf8; font-size: 1.8rem; font-weight: 700; margin-bottom: 0; line-height: 1.3;">Thank you for<br>reaching out!</h3>
                            </div>`;
                        }
                    } else {
                        var msg = (data && data.error) ? data.error
                            : (data && data.errors) ? data.errors.map(function (e) { return e.message; }).join(', ')
                                : 'Oops! There was a problem submitting your form';
                        var errBanner = form.querySelector('.contact-form-error');
                        if (!errBanner) {
                            errBanner = document.createElement('div');
                            errBanner.className = 'contact-form-error';
                            errBanner.style.cssText = 'color:#f87171;background:rgba(248,113,113,0.1);border:1px solid rgba(248,113,113,0.3);border-radius:0.5rem;padding:0.75rem 1rem;margin-bottom:0.75rem;font-size:0.875rem;';
                            form.insertBefore(errBanner, form.firstChild);
                        }
                        errBanner.textContent = msg;
                        errBanner.style.display = 'block';
                    }
                });
            }).catch(function (error) {
                var errBanner = form.querySelector('.contact-form-error');
                if (errBanner) { errBanner.textContent = 'Network error. Please try again.'; errBanner.style.display = 'block'; }
            }).finally(function () {
                submitBtn.innerText = originalBtnText;
                submitBtn.disabled = false;
            });
        });
    }

    // Close button
    var closeBtn = contactModal.querySelector('[data-contact-modal-close]');
    if (closeBtn) closeBtn.addEventListener('click', closeContactModal);

    // Click overlay to close
    contactModal.addEventListener('click', function (e) {
        if (e.target === contactModal) closeContactModal();
    });

    // Escape key
    document.addEventListener('keydown', function (e) {
        if (e.key === 'Escape' && contactModal.classList.contains('is-open')) closeContactModal();
    });

    // ── Language Switcher ──
    (function () {
        var path = window.location.pathname;
        var lang, basePath;

        if (path.indexOf('/zh-tw') === 0) {
            lang = 'zh-tw';
            basePath = path.replace(/^\/zh-tw/, '') || '/';
        } else if (path.indexOf('/zh-cn') === 0) {
            lang = 'zh-cn';
            basePath = path.replace(/^\/zh-cn/, '') || '/';
        } else {
            lang = 'en';
            basePath = path.replace(/^\/en-us/, '') || '/';
        }

        var labels = { 'en': 'EN', 'zh-tw': '繁中', 'zh-cn': '简中' };
        var current = labels[lang];
        var enHref = basePath || '/';
        var twHref = '/zh-tw' + (basePath || '/');
        var cnHref = '/zh-cn' + (basePath || '/');

        var options = [];
        if (lang !== 'en')   options.push({ label: 'EN',   href: enHref });
        if (lang !== 'zh-tw') options.push({ label: '繁中', href: twHref });
        if (lang !== 'zh-cn') options.push({ label: '简中', href: cnHref });

        // CSS
        if (!document.getElementById('daoai-lang-switcher-style')) {
            var s = document.createElement('style');
            s.id = 'daoai-lang-switcher-style';
            s.textContent = [
                '.lang-sw{position:relative;z-index:20;}',
                '.lang-sw-btn{align-items:center;background:transparent;border:1px solid rgba(255,255,255,0.2);border-radius:9999px;color:rgba(255,255,255,0.7);cursor:pointer;display:flex;font-family:Inter,-apple-system,sans-serif;font-size:0.8rem;font-weight:500;gap:4px;padding:0.35rem 0.75rem;transition:all 0.2s;}',
                '.lang-sw-btn:hover{color:#fff;border-color:rgba(255,255,255,0.4);}',
                '.lang-sw-drop{background:rgba(11,15,25,0.97);border:1px solid rgba(255,255,255,0.12);border-radius:8px;display:none;min-width:80px;overflow:hidden;position:absolute;right:0;top:calc(100% + 8px);box-shadow:0 8px 24px rgba(0,0,0,0.5);}',
                '.lang-sw.open .lang-sw-drop{display:block;}',
                '.lang-sw-drop a{color:rgba(255,255,255,0.7);display:block;font-family:Inter,-apple-system,sans-serif;font-size:0.85rem;font-weight:500;padding:0.55rem 1rem;text-decoration:none;transition:all 0.15s;}',
                '.lang-sw-drop a:hover{background:rgba(255,255,255,0.08);color:#fff;}',
                '@media(max-width:767px){.lang-sw{display:none!important;}}',
                '.mobile-lang-row{border-top:1px solid rgba(255,255,255,0.08);display:flex;gap:0.6rem;margin-top:1.5rem;padding-top:1rem;}',
                '.mobile-lang-row a{border:1px solid rgba(255,255,255,0.15);border-radius:9999px;color:rgba(255,255,255,0.65);font-family:Inter,-apple-system,sans-serif;font-size:0.85rem;font-weight:500;padding:0.25rem 0.75rem;text-decoration:none;transition:all 0.2s;}',
                '.mobile-lang-row a:hover{color:#fff;border-color:rgba(255,255,255,0.4);}'
            ].join('');
            document.head.appendChild(s);
        }

        // Desktop switcher — group CTA + lang-sw on the right
        var navContainer = (function () { var els = document.querySelectorAll('.header-nav .header-container'); for (var i = 0; i < els.length; i++) { if (!els[i].closest('[style*="display:none"]')) return els[i]; } return null; })();
        if (navContainer && !navContainer.querySelector('.lang-sw')) {
            var ctaBtn = navContainer.querySelector('.header-cta.desktop-only');
            var toggle = navContainer.querySelector('.header-mobile-toggle');

            // Build the lang switcher element
            var sw = document.createElement('div');
            sw.className = 'lang-sw';
            sw.innerHTML =
                '<button class="lang-sw-btn" aria-haspopup="true">' +
                    '<svg width="13" height="13" fill="none" stroke="currentColor" stroke-width="1.8" viewBox="0 0 24 24" style="opacity:.7">' +
                        '<circle cx="12" cy="12" r="10"/>' +
                        '<path d="M2 12h20M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"/>' +
                    '</svg>' +
                    current +
                    '<span style="font-size:.65rem;opacity:.55;margin-left:1px">▾</span>' +
                '</button>' +
                '<div class="lang-sw-drop">' +
                    options.map(function (o) { return '<a href="' + o.href + '">' + o.label + '</a>'; }).join('') +
                '</div>';

            // Wrap CTA + lang-sw together so they count as one flex item
            var rightGroup = document.createElement('div');
            rightGroup.className = 'header-right-group';
            rightGroup.style.cssText = 'align-items:center;display:flex;gap:0.75rem;z-index:20;';
            if (ctaBtn) {
                ctaBtn.parentNode.insertBefore(rightGroup, ctaBtn);
                rightGroup.appendChild(ctaBtn);
            } else if (toggle) {
                navContainer.insertBefore(rightGroup, toggle);
            } else {
                navContainer.appendChild(rightGroup);
            }
            rightGroup.appendChild(sw);

            sw.querySelector('.lang-sw-btn').addEventListener('click', function (e) {
                e.stopPropagation();
                sw.classList.toggle('open');
            });
            document.addEventListener('click', function () { sw.classList.remove('open'); });
        }

        // Mobile drawer
        var drawerInner = (function () { var els = document.querySelectorAll('.header-mobile-drawer .mobile-drawer-inner'); for (var i = 0; i < els.length; i++) { if (!els[i].closest('[style*="display:none"]')) return els[i]; } return null; })();
        if (drawerInner && !drawerInner.querySelector('.mobile-lang-row')) {
            var row = document.createElement('div');
            row.className = 'mobile-lang-row';
            row.innerHTML = options.map(function (o) { return '<a href="' + o.href + '">' + o.label + '</a>'; }).join('');
            drawerInner.appendChild(row);
        }
    })();

    // ── Scroll-hide: hide header on scroll down, show on scroll up ──
    (function () {
        var navEls = document.querySelectorAll('.header-nav');
        var scrollHeader = null;
        for (var i = 0; i < navEls.length; i++) {
            if (!navEls[i].closest('[style*="display:none"]')) { scrollHeader = navEls[i]; break; }
        }
        if (!scrollHeader) return;
        var lastY = 0;
        window.addEventListener('scroll', function () {
            var y = window.scrollY;
            if (y > lastY && y > 80) { scrollHeader.classList.add('header-hidden'); }
            else { scrollHeader.classList.remove('header-hidden'); }
            lastY = y;
        });
    })();
}

// Run immediately (HubSpot loads JS after DOM is ready)
if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', daoaiHeaderInit);
} else {
    daoaiHeaderInit();
}
